mapper.select:
SELECT /* getActiveUserCnt */
       COUNT(1)
 FROM TM_USERXM
 WHERE USER_NUMB = #{userNumb}
   AND USER_STAT = #{userStat}

mapper.insert:
INSERT IGNORE /* setNoticeView */
  INTO TB_USVIEW (
       VIEW_TYPE
     , TAGT_NUMB
     , USER_NUMB
     , REGI_DATE
) VALUES (
       #{viewType}
     , #{tagtNumb}
     , #{userNumb}
     , CURRENT_TIMESTAMP
)
